package tools

// linkifyfuzzy_test.go — differential golden test for the fuzzy bare-domain
// scanner. testdata/fuzzy_fuzz.json is generated by executing the real
// linkify-it (markdown-it's default instance, fuzzyEmail disabled to
// isolate fuzzy links) against hundreds of generated probe strings; the
// oracle records byte offsets, not JS UTF-16 indices. Regenerate only
// against the same pinned upstream version.

import (
	"encoding/json"
	"os"
	"testing"
)

type fuzzCase struct {
	Input string `json:"input"`
	Links []struct {
		Start int    `json:"start"`
		End   int    `json:"end"`
		Raw   string `json:"raw"`
		URL   string `json:"url"`
	} `json:"links"`
}

func TestScanFuzzyLinks_Differential(t *testing.T) {
	data, err := os.ReadFile("testdata/fuzzy_fuzz.json")
	if err != nil {
		t.Fatalf("read fuzz golden: %v", err)
	}
	var cases []fuzzCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatalf("parse fuzz golden: %v", err)
	}
	for _, tc := range cases {
		got := scanFuzzyLinks(tc.Input)
		if len(got) != len(tc.Links) {
			t.Fatalf("input %q: got %d links %v, want %d %v", tc.Input, len(got), got, len(tc.Links), tc.Links)
		}
		for i, m := range got {
			want := tc.Links[i]
			if m.start != want.Start || m.end != want.End {
				t.Fatalf("input %q: link %d = [%d,%d) %q, want [%d,%d) %q",
					tc.Input, i, m.start, m.end, tc.Input[m.start:m.end], want.Start, want.End, want.Raw)
			}
		}
	}
}

// TestNormalizeFuzzyURL checks the url/text production for each oracle
// match: href = normalizeMDLink("http://"+raw), display =
// normalizeMDLinkText("http://"+raw) minus the "http://" prefix. The
// oracle's url field carries linkify-it's normalize (http:// + raw); the
// markdown-it layer on top is verified through the convert goldens.
func TestNormalizeFuzzyURL_Roundtrip(t *testing.T) {
	data, err := os.ReadFile("testdata/fuzzy_fuzz.json")
	if err != nil {
		t.Fatalf("read fuzz golden: %v", err)
	}
	var cases []fuzzCase
	if err := json.Unmarshal(data, &cases); err != nil {
		t.Fatalf("parse fuzz golden: %v", err)
	}
	for _, tc := range cases {
		for _, l := range tc.Links {
			if got := "http://" + l.Raw; got != l.URL {
				t.Fatalf("input %q: oracle url %q, expected http:// + raw %q", tc.Input, l.URL, got)
			}
			href := normalizeMDLink("http://" + l.Raw)
			if href == "" {
				t.Fatalf("input %q: empty href for %q", tc.Input, l.Raw)
			}
		}
	}
}
